478	                    filters,
479	                    since: text("since"),
480	                    until: text("until"),
481	                    sort,
482	                    limit: int("limit").unwrap_or(5).clamp(1, 25),
483	                    offset: int("offset").unwrap_or(0),
484	                    fallback: true,
485	                };
486	                let outcome = self.store()?.search(&req)?;
487	                Ok(if json_out { serde_json::to_string(&outcome)? } else { render::search(&outcome) })
488	            }
