550	                    importance: int("importance").map(|i| i.min(255) as u8),
551	                    confidence: args.get("confidence").and_then(Value::as_f64),
552	                    source: text("source"),
553	                    refs: list_arg(args, "refs"),
554	                    pinned: bool_arg(args, "pinned"),
555	                    expires: text("expires"),
556	                    aliases: list_arg(args, "aliases"),
557	                    ns: text("ns"),
558	                };
